-- GENERATED by scripts/alchemy/build-harvest-migration.py — Sam, 2026-10-27: "I want all of this in databases and wired in the game".
-- Tables: ingredient_registry (Sam's 347-ingredient list), creature_harvest (who drops what on the kill). New items rows for
-- harvest parts the catalogue lacked; rarity from the creature's CR band (Xanathar's p.128-129, lib/harvest.ts).
-- Idempotent: tables `if not exists`, inserts `on conflict do nothing`. Existing items rows are NOT changed, except the three rarity fixes at the end (Sam: "fix to match").
begin;

create table if not exists public.ingredient_registry (
  slug text primary key,
  name text not null,
  category text not null,
  used_for text,
  gp numeric,
  provenance text not null check (provenance in ('spell-component','unverified','homebrew')),
  claimed_source text,
  evidence text,
  item_slug text references public.items(slug) on update cascade on delete set null,
  source_doc text not null default 'claude/alchemy_ingredient_list_2026-09-29.md',
  created_at timestamptz not null default now()
);
alter table public.ingredient_registry enable row level security;
drop policy if exists ingredient_registry_read on public.ingredient_registry;
create policy ingredient_registry_read on public.ingredient_registry for select to anon, authenticated using (true);

on conflict (slug) do nothing;

on conflict (slug) do nothing;

create table if not exists public.creature_harvest (
  id bigint generated always as identity primary key,
  bestiary_slug text not null references public.bestiary(slug) on update cascade on delete cascade,
  item_slug text not null references public.items(slug) on update cascade on delete cascade,
  qty integer not null default 1 check (qty > 0),
  note text,
  provenance text not null check (provenance in ('srd','book','spell-component','registry-unverified','registry-homebrew','catalogue','sam')),
  source text not null,
  created_at timestamptz not null default now(),
  harvest_check jsonb,
  unique (bestiary_slug, item_slug)
);
alter table public.creature_harvest enable row level security;
drop policy if exists creature_harvest_read on public.creature_harvest;
create policy creature_harvest_read on public.creature_harvest for select to anon, authenticated using (true);

on conflict (bestiary_slug, item_slug) do nothing;

-- link the list to the catalogue where the catalogue carries the part
update public.ingredient_registry r set item_slug = i.slug from public.items i where i.slug = r.slug and r.item_slug is null;
update public.ingredient_registry set item_slug = 'shrieker-rendered' where slug = 'shrieker' and item_slug is null;
update public.ingredient_registry set item_slug = 'rothe-meat' where slug = 'deep-rothe' and item_slug is null;
update public.ingredient_registry set item_slug = 'cavern-lizard-meat' where slug = 'riding-lizards' and item_slug is null;
update public.ingredient_registry set item_slug = 'carrion-crawler-mucus' where slug = 'carrion-crawler-mucus-venom' and item_slug is null;


-- Sam, 2026-10-27, gray ooze residue: "roll a medicine check to see if you can extract its residue like a poison you can apply to a
-- weapon or arrow for one combat set. Otherwise it hurts you." Then: DC 15, 1d6 acid on a fail, +1d6 acid on every hit for one combat.
alter table public.creature_harvest add column if not exists harvest_check jsonb;
update public.creature_harvest set harvest_check = '{"skill": "medicine", "dc": 15, "fail": {"dice": "1d6", "type": "acid"}, "ruled": "Sam 2026-10-27"}'::jsonb where bestiary_slug = 'gray-ooze' and item_slug = 'gray-ooze-residue';
update public.items set properties = coalesce(properties, '{}'::jsonb) || '{"harvest_check": {"skill": "medicine", "dc": 15, "fail": "1d6 acid to the harvester"}, "coating": {"applies_to": "a weapon or arrow", "lasts": "one combat", "on_hit": "+1d6 acid, every hit"}, "ruled": "Sam 2026-10-27"}'::jsonb where slug = 'gray-ooze-residue';

-- Sam, 2026-10-27: "fix to match" — three existing parts brought into their creature's Xanathar's CR band
update public.items set rarity = 'common', properties = coalesce(properties, '{}'::jsonb) || jsonb_build_object('rarity_rule', 'Xanathar''s p.128-129: harvest band of the creature''s CR (Quaggoth Thonot, CR 3)') where slug = 'thonot-psi-crystal';
update public.items set rarity = 'common', properties = coalesce(properties, '{}'::jsonb) || jsonb_build_object('rarity_rule', 'Xanathar''s p.128-129: harvest band of the creature''s CR (Carrion Crawler, CR 2)') where slug = 'carrion-crawler-mucus';
update public.items set rarity = 'very_rare', properties = coalesce(properties, '{}'::jsonb) || jsonb_build_object('rarity_rule', 'Xanathar''s p.128-129: harvest band of the creature''s CR (Beholder, CR 13)') where slug = 'beholder-central-eye';
commit;
